$calc$;

-- Forging - Dies
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Forging - Dies$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Forging - Dies$q$, 'process', 'single', false, true, true, $q$The forging dies over the lifetime volume: the finishing die's cavity machined at the tool shop rate (CNC setup and roughing rate per cubic inch of cavity, the forged volume), held within the range the data says that cost is valid in; the trim die at the least valid cost the data gives; one set lasts pressToolLifeNumberOfParts.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$The forging dies over the lifetime volume: the finishing die's cavity machined at the tool shop rate (CNC setup and roughing rate per cubic inch of cavity, the forged volume), held within the range the data says that cost is valid in; the trim die at the least valid cost the data gives; one set lasts pressToolLifeNumberOfParts.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Cavity Volume$q$, $q$Cavity Volume (mm³)$q$, $q$number$q$, $q$mm³$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$CNC Setup Time$q$, $q$CNC Setup Time (hr)$q$, $q$number$q$, $q$hr$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Roughing Rate$q$, $q$Roughing Rate (hr/in³)$q$, $q$number$q$, $q$hr/in³$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Machining Rate$q$, $q$Machining Rate (USD/hr)$q$, $q$number$q$, $q$USD/hr$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Min Finish Die Cost$q$, $q$Min Finish Die Cost (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Max Finish Die Cost$q$, $q$Max Finish Die Cost (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Trim Die Cost$q$, $q$Trim Die Cost (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Tool Life$q$, $q$Tool Life (parts)$q$, $q$number$q$, $q$parts$q$, NULL, NULL, NULL, NULL, 8, true),
    (v_id, $q$Lifetime Volume$q$, $q$Lifetime Volume (pcs)$q$, $q$number$q$, $q$pcs$q$, NULL, NULL, NULL, NULL, 9, true),
    (v_id, $q$Machined Die Cost$q$, $q$Machined Die Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q$({CNC Setup Time} + {Roughing Rate} * {Cavity Volume} / 16387.064) * {Machining Rate}$q$, 10, false),
    (v_id, $q$Finish Die Cost$q$, $q$Finish Die Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q$min(max({Machined Die Cost}, {Min Finish Die Cost}), {Max Finish Die Cost})$q$, 11, false),
    (v_id, $q$Die Sets$q$, $q$Die Sets$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$max(1, CEIL({Lifetime Volume} / {Tool Life}))$q$, 12, false),
    (v_id, $q$Tooling Cost$q$, $q$Tooling Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Die Sets} * ({Finish Die Cost} + {Trim Die Cost})$q$, 13, false),
    (v_id, $q$Cost per Part$q$, $q$Cost per Part (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Tooling Cost} / {Lifetime Volume}$q$, 14, false);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Forging - Forged volume$q$, 6, 0),
    ($q$Forging - Flash land$q$, 10, 0),
    ($q$Forging - Bar stock$q$, 12, 0),
    ($q$Forging - Band saw$q$, 7, 1),
    ($q$Forging - Induction heating$q$, 7, 1),
    ($q$Forging - Press force$q$, 10, 0),
    ($q$Forging - Press$q$, 6, 1),
    ($q$Forging - Trim force$q$, 4, 0),
    ($q$Forging - Trim$q$, 5, 1),
    ($q$Forging - Dies$q$, 14, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Forging$q$) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1053: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
